SELECT *
FROM tb_ai_log_sync_task
WHERE id > #{afterId}
  AND environment = #{environment}
  AND system_code = #{systemCode}
  AND status IN ('PENDING', 'RUNNING')
ORDER BY id ASC
LIMIT #{limit}

SELECT *
FROM tb_ai_log_sync_task
WHERE environment = #{environment}
  AND system_code = #{systemCode}
  AND log_date = #{logDate}
